// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** An outpatient's or emergency patient's referral to another facility (the clinic manual, indicator 29). */
export interface ReferralIn {
  /** The OPD visit */
  ticket_id?: number | null;
  /** The emergency visit */
  er_visit_id?: number | null;
  /** The consultation note (not an inpatient's: use the admission's transfer or referral slip) */
  encounter_id?: number | null;
  /** The facility from the contact list (GET /mlc/contacts) */
  destination_contact_id?: number | null;
  /** Default: the contact's name; the facility the patient chooses when they ask to go */
  destination_name?: string | null;
  destination_department?: string | null;
  reason: string;
  urgency: "Routine" | "Urgent" | "Emergency";
  /** Symptoms, findings and the provisional diagnosis for the receiving doctor */
  clinical_summary: string;
  treatment_given?: string | null;
  /** The patient asked to go elsewhere (the note says so) */
  at_patient_request?: boolean;
  /** WithStaff: the establishment's staff take the patient; the receiving facility's acknowledgement is then recorded (POST /referrals/{id}/acknowledge) */
  transport: "Own" | "Ambulance" | "Rescue" | "WithStaff";
  /** Required for WithStaff: who goes with the patient */
  escort_name?: string | null;
  /** Oxygen, a drip, monitoring on the way */
  care_during_transfer?: string | null;
}

export interface ReferralOut {
  referral_id: number;
  referral_number: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  father_or_husband_name: string | null;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  address: string | null;
  mobile: string | null;
  ticket_id: number | null;
  er_visit_id: number | null;
  encounter_id: number | null;
  referred_by: number;
  referred_by_name: string;
  referred_by_stamp: AuthorStampOut;
  destination_contact_id: number | null;
  destination_name: string;
  destination_department: string | null;
  reason: string;
  urgency: "Routine" | "Urgent" | "Emergency";
  clinical_summary: string;
  treatment_given: string | null;
  at_patient_request: boolean;
  transport: "Own" | "Ambulance" | "Rescue" | "WithStaff";
  escort_name: string | null;
  care_during_transfer: string | null;
  status: "Issued" | "Acknowledged" | "Cancelled";
  acknowledged_by_name: string | null;
  acknowledged_at: string | null;
  acknowledgement_note: string | null;
  cancel_reason: string | null;
  cancelled_at: string | null;
  created_at: string;
  row_version: number;
  /** Our staff took the patient and the receiving facility's acknowledgement is not recorded yet */
  acknowledgement_pending: boolean;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface ReferralAcknowledgeIn {
  acknowledged_by_name: string;
  /** Between issue and now, with timezone; default: now */
  acknowledged_at?: string | null;
  note?: string | null;
}

export interface ReferralCancelIn {
  reason: string;
}

export interface MlcContactOut {
  contact_id: number;
  contact_type: "PoliceStation" | "MlrHospital" | "ReferralHospital" | "HealthOffice" | "TraumaCentre" | "BloodBank" | "RescueService" | "FireBrigade" | "PoliceEmergency" | "Ambulance" | "SocialService";
  name: string;
  district: string | null;
  phone: string | null;
  alt_phone: string | null;
  address: string | null;
  notes: string | null;
  is_active: boolean;
}

/** Refer an outpatient or emergency patient to another facility — POST /api/v1/referrals (who may call: holders of referral.create). */
export function createReferrals(body: ReferralIn): Promise<ReferralOut> {
  return api<ReferralOut>("POST", `/referrals`, body, { idempotent: true });
}

/** One referral — GET /api/v1/referrals/{referral_id} (who may call: holders of referral.view or referral.create). */
export function getReferrals(referral_id: number): Promise<ReferralOut> {
  return api<ReferralOut>("GET", `/referrals/${referral_id}`, undefined);
}

/** Record the receiving facility's acknowledgement — POST /api/v1/referrals/{referral_id}/acknowledge (who may call: holders of referral.create). */
export function acknowledgeReferrals(referral_id: number, body: ReferralAcknowledgeIn): Promise<ReferralOut> {
  return api<ReferralOut>("POST", `/referrals/${referral_id}/acknowledge`, body);
}

/** Cancel a referral that did not happen — POST /api/v1/referrals/{referral_id}/cancel (who may call: holders of referral.create). */
export function cancelReferrals(referral_id: number, body: ReferralCancelIn): Promise<ReferralOut> {
  return api<ReferralOut>("POST", `/referrals/${referral_id}/cancel`, body);
}

/** The referral letter (PDF) — GET /api/v1/referrals/{referral_id}/pdf (who may call: holders of referral.view or referral.create). */
export function letter(referral_id: number): Promise<unknown> {
  return api<unknown>("GET", `/referrals/${referral_id}/pdf`, undefined);
}

/** Police stations and MLR hospitals (contact list) — GET /api/v1/mlc/contacts (who may call: holders of mlc.case.manage or mlc.register.view or mlc.setup.manage). */
export function contacts(query?: { contact_type?: "PoliceStation" | "MlrHospital" | "ReferralHospital" | "HealthOffice" | "TraumaCentre" | "BloodBank" | "RescueService" | "FireBrigade" | "PoliceEmergency" | "Ambulance" | "SocialService" | null; include_inactive?: boolean }): Promise<MlcContactOut[]> {
  return api<MlcContactOut[]>("GET", withQuery(`/mlc/contacts`, query), undefined);
}
